SELECT COUNT(*) FROM employees WHERE status='Aktif'; SELECT COUNT(*) FROM contracts WHERE status='Aktif' AND end_date>=date('now'); SELECT COUNT(*) FROM contracts WHERE status='Aktif' AND end_date BETWEEN date('now') AND date('now','+30 days'); SELECT COUNT(*) FROM issues WHERE status!='Done'; SELECT COUNT(*) FROM one_on_one WHERE status!='Done'; SELECT COUNT(*) FROM activity_schedule; SELECT COUNT(*) FROM supply_requests WHERE status='Pending'; SELECT COUNT(*) FROM branches WHERE is_active=1; SELECT backup_date, status FROM relievers; SELECT AVG(fc_score) as avg_fc, AVG(spv_score) as avg_spv FROM inspection_reports;
